using System;
using System.Collections.Generic;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests;

public class PaginatedListTests
{
    private IQueryable<string> CreateSource(int count)
    {
        return Enumerable.Range(1, count).Select(i => $"Item{i}").AsQueryable();
    }

    [Fact]
    public void Create_FirstPage_ReturnsCorrectItems()
    {
        var source = CreateSource(25);

        var result = PaginatedList<string>.Create(source, pageIndex: 1, pageSize: 10);

        Assert.Equal(10, result.Count);
        Assert.Equal("Item1", result[0]);
        Assert.Equal("Item10", result[9]);
        Assert.Equal(1, result.PageIndex);
    }

    [Fact]
    public void Create_SecondPage_SkipsFirstPageItems()
    {
        var source = CreateSource(25);

        var result = PaginatedList<string>.Create(source, pageIndex: 2, pageSize: 10);

        Assert.Equal(10, result.Count);
        Assert.Equal("Item11", result[0]);
        Assert.Equal("Item20", result[9]);
        Assert.Equal(2, result.PageIndex);
    }

    [Fact]
    public void Create_LastPage_ReturnsRemainingItems()
    {
        var source = CreateSource(25);

        var result = PaginatedList<string>.Create(source, pageIndex: 3, pageSize: 10);

        Assert.Equal(5, result.Count);
        Assert.Equal("Item21", result[0]);
        Assert.Equal("Item25", result[4]);
    }

    [Fact]
    public void TotalPages_CalculatedCorrectly_WithExactDivision()
    {
        var source = CreateSource(30);

        var result = PaginatedList<string>.Create(source, 1, 10);

        Assert.Equal(3, result.TotalPages);
    }

    [Fact]
    public void TotalPages_RoundsUp_WithRemainder()
    {
        var source = CreateSource(25);

        var result = PaginatedList<string>.Create(source, 1, 10);

        // 25 / 10 = 2.5 → ceiling = 3
        Assert.Equal(3, result.TotalPages);
    }

    [Fact]
    public void TotalPages_SingleItem_ReturnsSinglePage()
    {
        var source = CreateSource(1);

        var result = PaginatedList<string>.Create(source, 1, 10);

        Assert.Equal(1, result.TotalPages);
        Assert.Single(result);
    }

    [Fact]
    public void HasPreviousPage_OnFirstPage_ReturnsFalse()
    {
        var source = CreateSource(25);

        var result = PaginatedList<string>.Create(source, 1, 10);

        Assert.False(result.HasPreviousPage);
    }

    [Fact]
    public void HasPreviousPage_OnSecondPage_ReturnsTrue()
    {
        var source = CreateSource(25);

        var result = PaginatedList<string>.Create(source, 2, 10);

        Assert.True(result.HasPreviousPage);
    }

    [Fact]
    public void HasNextPage_OnLastPage_ReturnsFalse()
    {
        var source = CreateSource(25);

        var result = PaginatedList<string>.Create(source, 3, 10);

        Assert.False(result.HasNextPage);
    }

    [Fact]
    public void HasNextPage_OnFirstPage_ReturnsTrue()
    {
        var source = CreateSource(25);

        var result = PaginatedList<string>.Create(source, 1, 10);

        Assert.True(result.HasNextPage);
    }

    [Fact]
    public void HasNextPage_SinglePageExact_ReturnsFalse()
    {
        var source = CreateSource(10);

        var result = PaginatedList<string>.Create(source, 1, 10);

        Assert.False(result.HasNextPage);
        Assert.False(result.HasPreviousPage);
    }

    [Fact]
    public void Constructor_SetsPropertiesCorrectly()
    {
        var items = new List<int> { 1, 2, 3 };

        var paginatedList = new PaginatedList<int>(items, count: 30, pageIndex: 2, pageSize: 10);

        Assert.Equal(2, paginatedList.PageIndex);
        Assert.Equal(3, paginatedList.TotalPages);
        Assert.Equal(3, paginatedList.Count);
        Assert.Contains(1, paginatedList);
        Assert.Contains(2, paginatedList);
        Assert.Contains(3, paginatedList);
    }

    [Fact]
    public void Create_EmptySource_ReturnsEmptyListWithZeroPages()
    {
        var source = Enumerable.Empty<string>().AsQueryable();

        var result = PaginatedList<string>.Create(source, 1, 10);

        Assert.Empty(result);
        Assert.Equal(0, result.TotalPages);
        Assert.False(result.HasNextPage);
        Assert.False(result.HasPreviousPage);
    }

    [Fact]
    public void Create_PageSizeOfOne_PaginatesCorrectly()
    {
        var source = CreateSource(5);

        var result = PaginatedList<string>.Create(source, 3, 1);

        Assert.Single(result);
        Assert.Equal("Item3", result[0]);
        Assert.Equal(5, result.TotalPages);
        Assert.True(result.HasPreviousPage);
        Assert.True(result.HasNextPage);
    }
}

