using System;
using Xunit;

namespace ContosoUniversity.Tests;

public class NotificationServiceTests : IDisposable
{
    private readonly NotificationService _sut = new();

    public void Dispose() => _sut.Dispose();

    // --- SendNotification ---

    [Fact]
    public void SendNotification_Create_EnqueuesNotificationThatCanBeReceived()
    {
        _sut.SendNotification("Student", "42", "John Doe", EntityOperation.CREATE, "admin");

        var notification = _sut.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal("Student", notification.EntityType);
        Assert.Equal("42", notification.EntityId);
        Assert.Equal("CREATE", notification.Operation);
        Assert.Contains("John Doe", notification.Message);
        Assert.Contains("created", notification.Message);
        Assert.Equal("admin", notification.CreatedBy);
        Assert.False(notification.IsRead);
    }

    [Fact]
    public void SendNotification_Update_GeneratesUpdateMessage()
    {
        _sut.SendNotification("Course", "101", "Chemistry", EntityOperation.UPDATE, "teacher");

        var notification = _sut.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal("UPDATE", notification.Operation);
        Assert.Contains("updated", notification.Message);
        Assert.Contains("Chemistry", notification.Message);
    }

    [Fact]
    public void SendNotification_Delete_GeneratesDeleteMessage()
    {
        _sut.SendNotification("Department", "5", "Engineering", EntityOperation.DELETE);

        var notification = _sut.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal("DELETE", notification.Operation);
        Assert.Contains("deleted", notification.Message);
        Assert.Contains("Engineering", notification.Message);
    }

    [Fact]
    public void SendNotification_NullUserName_DefaultsToSystem()
    {
        _sut.SendNotification("Student", "1", EntityOperation.CREATE, null);

        var notification = _sut.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal("System", notification.CreatedBy);
    }

    [Fact]
    public void SendNotification_NoDisplayName_UsesIdInMessage()
    {
        _sut.SendNotification("Student", "99", EntityOperation.CREATE, "admin");

        var notification = _sut.ReceiveNotification();

        Assert.NotNull(notification);
        // When no display name, message should include the ID
        Assert.Contains("99", notification.Message);
    }

    [Fact]
    public void SendNotification_WithDisplayName_UsesDisplayNameInMessage()
    {
        _sut.SendNotification("Student", "99", "Jane Smith", EntityOperation.CREATE, "admin");

        var notification = _sut.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Contains("Jane Smith", notification.Message);
    }

    [Fact]
    public void SendNotification_SetsCreatedAtToApproximatelyNow()
    {
        var before = DateTime.Now.AddSeconds(-1);

        _sut.SendNotification("Student", "1", EntityOperation.CREATE);

        var after = DateTime.Now.AddSeconds(1);
        var notification = _sut.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.InRange(notification.CreatedAt, before, after);
    }

    // --- ReceiveNotification ---

    [Fact]
    public void ReceiveNotification_EmptyQueue_ReturnsNull()
    {
        // Drain any notifications left by other tests (static queue)
        while (_sut.ReceiveNotification() != null) { }

        var result = _sut.ReceiveNotification();

        Assert.Null(result);
    }

    [Fact]
    public void ReceiveNotification_MultipleNotifications_ReturnsFIFOOrder()
    {
        // Drain first
        while (_sut.ReceiveNotification() != null) { }

        _sut.SendNotification("A", "1", EntityOperation.CREATE);
        _sut.SendNotification("B", "2", EntityOperation.UPDATE);
        _sut.SendNotification("C", "3", EntityOperation.DELETE);

        var first = _sut.ReceiveNotification();
        var second = _sut.ReceiveNotification();
        var third = _sut.ReceiveNotification();

        Assert.Equal("A", first!.EntityType);
        Assert.Equal("B", second!.EntityType);
        Assert.Equal("C", third!.EntityType);
    }

    [Fact]
    public void ReceiveNotification_DequeuedItem_IsNotReturnedAgain()
    {
        // Drain first
        while (_sut.ReceiveNotification() != null) { }

        _sut.SendNotification("X", "1", EntityOperation.CREATE);

        var first = _sut.ReceiveNotification();
        var second = _sut.ReceiveNotification();

        Assert.NotNull(first);
        Assert.Null(second);
    }

    // --- MarkAsRead ---

    [Fact]
    public void MarkAsRead_DoesNotThrow()
    {
        // MarkAsRead is a no-op in the in-memory implementation
        var exception = Record.Exception(() => _sut.MarkAsRead(999));

        Assert.Null(exception);
    }

    // --- Overload without display name ---

    [Fact]
    public void SendNotification_OverloadWithoutDisplayName_FallsBackToIdFormat()
    {
        // Drain first
        while (_sut.ReceiveNotification() != null) { }

        _sut.SendNotification("Department", "7", EntityOperation.UPDATE, "user1");

        var notification = _sut.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal("Department", notification.EntityType);
        Assert.Equal("7", notification.EntityId);
        Assert.Contains("ID: 7", notification.Message);
        Assert.Equal("user1", notification.CreatedBy);
    }

    // --- Message generation per operation ---

    [Theory]
    [InlineData(EntityOperation.CREATE, "created")]
    [InlineData(EntityOperation.UPDATE, "updated")]
    [InlineData(EntityOperation.DELETE, "deleted")]
    public void SendNotification_OperationType_GeneratesCorrectVerb(EntityOperation operation, string expectedVerb)
    {
        // Drain first
        while (_sut.ReceiveNotification() != null) { }

        _sut.SendNotification("Test", "1", "TestEntity", operation, "user");

        var notification = _sut.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Contains(expectedVerb, notification.Message);
    }
}

