using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using System;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests;

public class StudentsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly StudentsController _sut;

    public StudentsControllerTests()
    {
        _context = TestHelpers.CreateSeededContext();
        _sut = new StudentsController(_context);
    }

    public void Dispose()
    {
        _sut.Dispose();
        _context.Dispose();
    }

    // --- Index ---

    [Fact]
    public void Index_NoSearchOrSort_ReturnsViewWithStudentsOrderedByLastName()
    {
        var result = _sut.Index(null, null, null, null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Equal(3, model.Count);
        // Default sort is by LastName ascending
        Assert.Equal("Alexander", model[0].LastName);
        Assert.Equal("Alonso", model[1].LastName);
        Assert.Equal("Anand", model[2].LastName);
    }

    [Fact]
    public void Index_SortByNameDesc_ReturnsStudentsInDescendingOrder()
    {
        var result = _sut.Index("name_desc", null, null, null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Equal("Anand", model[0].LastName);
        Assert.Equal("Alonso", model[1].LastName);
        Assert.Equal("Alexander", model[2].LastName);
    }

    [Fact]
    public void Index_SortByDate_ReturnsStudentsOrderedByEnrollmentDate()
    {
        var result = _sut.Index("Date", null, null, null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        // 2010, 2012, 2013
        Assert.Equal("Alexander", model[0].LastName);
        Assert.Equal("Alonso", model[1].LastName);
        Assert.Equal("Anand", model[2].LastName);
    }

    [Fact]
    public void Index_SortByDateDesc_ReturnsStudentsInDescendingDateOrder()
    {
        var result = _sut.Index("date_desc", null, null, null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        // 2013, 2012, 2010
        Assert.Equal("Anand", model[0].LastName);
        Assert.Equal("Alonso", model[1].LastName);
        Assert.Equal("Alexander", model[2].LastName);
    }

    [Fact]
    public void Index_SearchByLastName_FiltersResults()
    {
        var result = _sut.Index(null, null, "Alexander", null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Single(model);
        Assert.Equal("Alexander", model[0].LastName);
    }

    [Fact]
    public void Index_SearchByFirstName_FiltersResults()
    {
        var result = _sut.Index(null, null, "Meredith", null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Single(model);
        Assert.Equal("Alonso", model[0].LastName);
    }

    [Fact]
    public void Index_SearchStringProvided_ResetsPageToOne()
    {
        var result = _sut.Index(null, null, "A", 5) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Equal(1, model.PageIndex);
    }

    [Fact]
    public void Index_NoSearchString_UsesCurrentFilter()
    {
        var result = _sut.Index(null, "Alexander", null, null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Single(model);
        Assert.Equal("Alexander", model[0].LastName);
    }

    [Fact]
    public void Index_SetsViewBagSortParams()
    {
        var result = _sut.Index(null, null, null, null) as ViewResult;

        Assert.Null(result!.ViewData["CurrentSort"]);
        Assert.Equal("name_desc", _sut.ViewBag.NameSortParm);
        Assert.Equal("Date", _sut.ViewBag.DateSortParm);
    }

    [Fact]
    public void Index_WithSortOrder_NameSortParmToggles()
    {
        // When sortOrder is "name_desc", NameSortParm should toggle to ""
        _sut.Index("name_desc", null, null, null);
        Assert.Equal("", _sut.ViewBag.NameSortParm);

        // When sortOrder is "Date", DateSortParm toggles to "date_desc"
        _sut.Index("Date", null, null, null);
        Assert.Equal("date_desc", _sut.ViewBag.DateSortParm);
    }

    // --- Details ---

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        var result = _sut.Details(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Details_ValidId_ReturnsViewWithStudent()
    {
        var result = _sut.Details(10) as ViewResult;

        Assert.NotNull(result);
        var student = Assert.IsType<Student>(result.Model);
        Assert.Equal("Alexander", student.LastName);
        Assert.Equal("Carson", student.FirstMidName);
    }

    [Fact]
    public void Details_ValidId_IncludesEnrollmentsWithCourse()
    {
        var result = _sut.Details(10) as ViewResult;

        var student = Assert.IsType<Student>(result!.Model);
        Assert.NotNull(student.Enrollments);
        Assert.NotEmpty(student.Enrollments);
        // Verify that the enrollment data is present
        var enrollment = student.Enrollments.First();
        Assert.Equal(Grade.A, enrollment.Grade);
    }

    // --- Create GET ---

    [Fact]
    public void Create_Get_ReturnsViewWithDefaultStudent()
    {
        var result = _sut.Create() as ViewResult;

        Assert.NotNull(result);
        var student = Assert.IsType<Student>(result.Model);
        Assert.Equal(DateTime.Today, student.EnrollmentDate);
    }

    // --- Create POST ---

    [Fact]
    public void Create_Post_ValidStudent_RedirectsToIndex()
    {
        var student = new Student
        {
            FirstMidName = "Test",
            LastName = "Student",
            EnrollmentDate = new DateTime(2020, 9, 1)
        };

