using ContosoUniversity.Models;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Logging;
using Moq;
using System;
using System.IO;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests;

public class CoursesControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly Mock<IWebHostEnvironment> _mockEnv;
    private readonly Mock<ILogger<CoursesController>> _mockLogger;
    private readonly CoursesController _sut;

    public CoursesControllerTests()
    {
        _context = TestHelpers.CreateSeededContext();
        _mockEnv = new Mock<IWebHostEnvironment>();
        _mockEnv.Setup(e => e.WebRootPath).Returns(Path.GetTempPath());
        _mockEnv.Setup(e => e.ContentRootPath).Returns(Path.GetTempPath());
        _mockLogger = new Mock<ILogger<CoursesController>>();
        _sut = new CoursesController(_context, _mockEnv.Object, _mockLogger.Object);
    }

    public void Dispose()
    {
        _sut.Dispose();
        _context.Dispose();
    }

    // --- Index ---

    [Fact]
    public void Index_ReturnsViewWithAllCourses()
    {
        var result = _sut.Index() as ViewResult;

        Assert.NotNull(result);
        var courses = Assert.IsAssignableFrom<System.Collections.Generic.List<Course>>(result.Model);
        Assert.Equal(2, courses.Count);
    }

    // --- Details ---

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        var result = _sut.Details(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Details_ValidId_ReturnsViewWithCourse()
    {
        var result = _sut.Details(1050) as ViewResult;

        Assert.NotNull(result);
        var course = Assert.IsType<Course>(result.Model);
        Assert.Equal("Chemistry", course.Title);
        Assert.Equal(3, course.Credits);
    }

    // --- Create GET ---

    [Fact]
    public void Create_Get_ReturnsViewWithEmptyCourse()
    {
        var result = _sut.Create() as ViewResult;

        Assert.NotNull(result);
        var course = Assert.IsType<Course>(result.Model);
        Assert.Equal(0, course.CourseID);
    }

    [Fact]
    public void Create_Get_PopulatesDepartmentSelectList()
    {
        _sut.Create();

        Assert.NotNull(_sut.ViewBag.DepartmentID);
    }

    // --- Create POST ---

    [Fact]
    public void Create_Post_ValidCourse_NoImage_RedirectsToIndex()
    {
        var course = new Course
        {
            CourseID = 9999,
            Title = "New Course",
            Credits = 3,
            DepartmentID = 1
        };

        var result = _sut.Create(course, null!);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
    }

    [Fact]
    public void Create_Post_ValidCourse_SavesDatabase()
    {
        var course = new Course
        {
            CourseID = 8888,
            Title = "Saved Course",
            Credits = 4,
            DepartmentID = 1
        };

        _sut.Create(course, null!);

        var saved = _context.Courses.Find(8888);
        Assert.NotNull(saved);
        Assert.Equal("Saved Course", saved.Title);
        Assert.Equal(4, saved.Credits);
    }

    [Fact]
    public void Create_Post_InvalidExtension_AddsModelError()
    {
        var course = new Course { CourseID = 7777, Title = "Test", Credits = 3, DepartmentID = 1 };
        var mockFile = CreateMockFormFile("test.exe", 1024);

        var result = _sut.Create(course, mockFile.Object) as ViewResult;

        Assert.NotNull(result);
        Assert.True(_sut.ModelState.ContainsKey("teachingMaterialImage"));
        var error = _sut.ModelState["teachingMaterialImage"]!.Errors[0].ErrorMessage;
        Assert.Contains("valid image file", error);
    }

    [Fact]
    public void Create_Post_FileTooLarge_AddsModelError()
    {
        var course = new Course { CourseID = 7777, Title = "Test", Credits = 3, DepartmentID = 1 };
        var mockFile = CreateMockFormFile("test.jpg", 6 * 1024 * 1024); // 6MB > 5MB limit

        var result = _sut.Create(course, mockFile.Object) as ViewResult;

        Assert.NotNull(result);
        Assert.True(_sut.ModelState.ContainsKey("teachingMaterialImage"));
        var error = _sut.ModelState["teachingMaterialImage"]!.Errors[0].ErrorMessage;
        Assert.Contains("5MB", error);
    }

    [Fact]
    public void Create_Post_InvalidModelState_ReturnsView()
    {
        _sut.ModelState.AddModelError("Title", "Required");
        var course = new Course { CourseID = 7777, Credits = 3, DepartmentID = 1 };

        var result = _sut.Create(course, null!) as ViewResult;

        Assert.NotNull(result);
    }

    [Theory]
    [InlineData(".jpg")]
    [InlineData(".jpeg")]
    [InlineData(".png")]
    [InlineData(".gif")]
    [InlineData(".bmp")]
    public void Create_Post_ValidImageExtension_Accepted(string extension)
    {
        var course = new Course { CourseID = 5555, Title = "ImageTest", Credits = 3, DepartmentID = 1 };
        var mockFile = CreateMockFormFile($"test{extension}", 1024);

        var result = _sut.Create(course, mockFile.Object);

        // Should redirect (not return view with error)
        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
    }

    // --- Edit GET ---

    [Fact]
    public void Edit_Get_NullId_ReturnsBadRequest()
    {
        var result = _sut.Edit(null);

        Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, ((StatusCodeResult)result).StatusCode);
    }

    [Fact]
    public void Edit_Get_ValidId_ReturnsViewWithCourse()
    {
        var result = _sut.Edit(1050) as ViewResult;

        Assert.NotNull(result);
        var course = Assert.IsType<Course>(result.Model);
        Assert.Equal("Chemistry", course.Title);
    }

    [Fact]
    public void Edit_Get_InvalidId_ReturnsNotFound()
    {
        var result = _sut.Edit(9999);

        Assert.IsType<NotFoundResult>(result);
    }

    // --- Edit POST ---

    [Fact]
    public void Edit_Post_ValidCourse_NoImage_RedirectsToIndex()
    {
        var course = _context.Courses.AsNoTracking().First(c => c.CourseID == 1050);
        course.Title = "Updated Chemistry";

        var result = _sut.Edit(course, null!);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
    }

    [Fact]
    public void Edit_Post_ValidCourse_UpdatesDatabase()
    {
        var course = _context.Courses.AsNoTracking().First(c => c.CourseID == 1050);
        course.Title = "Modified Title";

        _sut.Edit(course, null!);

        var updated = _context.Courses.Find(1050);
        Assert.Equal("Modified Title", updated!.Title);
    }

    [Fact]
    public void Edit_Post_InvalidExtension_AddsModelError()
    {
        var course = _context.Courses.AsNoTracking().First(c => c.CourseID == 1050);
        var mockFile = CreateMockFormFile("virus.bat", 1024);

        var result = _sut.Edit(course, mockFile.Object) as ViewResult;

        Assert.NotNull(result);
        Assert.True(_sut.ModelState.ContainsKey("teachingMaterialImage"));
    }

    // --- Delete GET ---

    [Fact]
    public void Delete_Get_NullId_ReturnsBadRequest()
    {
        var result = _sut.Delete(null);

        Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, ((StatusCodeResult)result).StatusCode);
    }

    [Fact]
    public void Delete_Get_ValidId_ReturnsViewWithCourse()
    {
        var result = _sut.Delete(1050) as ViewResult;

        Assert.NotNull(result);
        var course = Assert.IsType<Course>(result.Model);
        Assert.Equal("Chemistry", course.Title);
    }

    // --- DeleteConfirmed ---

    [Fact]
    public void DeleteConfirmed_RemovesCourseAndRedirects()
    {
        var countBefore = _context.Courses.Count();

        var result = _sut.DeleteConfirmed(1050);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
        Assert.Equal(countBefore - 1, _context.Courses.Count());
    }

    // --- Helper ---

    private static Mock<IFormFile> CreateMockFormFile(string fileName, long length)
    {
        var mockFile = new Mock<IFormFile>();
        mockFile.Setup(f => f.FileName).Returns(fileName);
        mockFile.Setup(f => f.Length).Returns(length);
        mockFile.Setup(f => f.CopyTo(It.IsAny<Stream>()));
        return mockFile;
    }
}

