using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using System;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests;

public class DepartmentsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly DepartmentsController _sut;

    public DepartmentsControllerTests()
    {
        _context = TestHelpers.CreateSeededContext();
        _sut = new DepartmentsController(_context);
    }

    public void Dispose()
    {
        _sut.Dispose();
        _context.Dispose();
    }

    // --- Index ---

    [Fact]
    public void Index_ReturnsViewWithAllDepartments()
    {
        var result = _sut.Index() as ViewResult;

        Assert.NotNull(result);
        var departments = Assert.IsAssignableFrom<System.Collections.Generic.List<Department>>(result.Model);
        Assert.Equal(2, departments.Count);
    }

    // --- Details ---

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        var result = _sut.Details(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Details_ValidId_ReturnsViewWithDepartment()
    {
        var result = _sut.Details(1) as ViewResult;

        Assert.NotNull(result);
        var dept = Assert.IsType<Department>(result.Model);
        Assert.Equal("English", dept.Name);
        Assert.Equal(350000m, dept.Budget);
    }

    [Fact]
    public void Details_InvalidId_ReturnsNotFound()
    {
        var result = _sut.Details(9999);

        Assert.IsType<NotFoundResult>(result);
    }

    // --- Create GET ---

    [Fact]
    public void Create_Get_ReturnsView()
    {
        var result = _sut.Create() as ViewResult;

        Assert.NotNull(result);
        Assert.NotNull(_sut.ViewBag.InstructorID);
    }

    // --- Create POST ---

    [Fact]
    public void Create_Post_ValidDepartment_RedirectsToIndex()
    {
        var department = new Department
        {
            Name = "Physics",
            Budget = 200000,
            StartDate = new DateTime(2020, 1, 1),
            InstructorID = 1
        };

        var result = _sut.Create(department);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
    }

    [Fact]
    public void Create_Post_ValidDepartment_SavesDatabase()
    {
        var department = new Department
        {
            Name = "Physics",
            Budget = 200000,
            StartDate = new DateTime(2020, 1, 1),
            InstructorID = 1
        };

        _sut.Create(department);

        var saved = _context.Departments.FirstOrDefault(d => d.Name == "Physics");
        Assert.NotNull(saved);
        Assert.Equal(200000m, saved.Budget);
        Assert.Equal(1, saved.InstructorID);
    }

    [Fact]
    public void Create_Post_InvalidModelState_ReturnsView()
    {
        _sut.ModelState.AddModelError("Name", "Required");
        var department = new Department
        {
            Budget = 100000,
            StartDate = new DateTime(2020, 1, 1)
        };

        var result = _sut.Create(department) as ViewResult;

        Assert.NotNull(result);
        Assert.Equal(department, result.Model);
    }

    // --- Edit GET ---

    [Fact]
    public void Edit_Get_NullId_ReturnsBadRequest()
    {
        var result = _sut.Edit(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Edit_Get_ValidId_ReturnsViewWithDepartment()
    {
        var result = _sut.Edit(1) as ViewResult;

        Assert.NotNull(result);
        var dept = Assert.IsType<Department>(result.Model);
        Assert.Equal("English", dept.Name);
    }

    [Fact]
    public void Edit_Get_InvalidId_ReturnsNotFound()
    {
        var result = _sut.Edit(9999);

        Assert.IsType<NotFoundResult>(result);
    }

    // --- Edit POST ---

    [Fact]
    public void Edit_Post_ValidDepartment_RedirectsToIndex()
    {
        var dept = _context.Departments.AsNoTracking().First(d => d.DepartmentID == 1);
        dept.Name = "UpdatedEnglish";

        var result = _sut.Edit(dept);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
    }

    [Fact]
    public void Edit_Post_ValidDepartment_UpdatesDatabase()
    {
        var dept = _context.Departments.AsNoTracking().First(d => d.DepartmentID == 1);
        dept.Budget = 999999;

        _sut.Edit(dept);

        var updated = _context.Departments.Find(1);
        Assert.Equal(999999m, updated!.Budget);
    }

    [Fact]
    public void Edit_Post_InvalidModelState_ReturnsView()
    {
        _sut.ModelState.AddModelError("Name", "Required");
        var dept = new Department
        {
            DepartmentID = 1,
            Budget = 100000,
            StartDate = new DateTime(2020, 1, 1)
        };

        var result = _sut.Edit(dept) as ViewResult;

        Assert.NotNull(result);
    }

    // --- Delete GET ---

    [Fact]
    public void Delete_Get_NullId_ReturnsBadRequest()
    {
        var result = _sut.Delete(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Delete_Get_ValidId_ReturnsViewWithDepartment()
    {
        var result = _sut.Delete(1) as ViewResult;

        Assert.NotNull(result);
        var dept = Assert.IsType<Department>(result.Model);
        Assert.Equal("English", dept.Name);
    }

    [Fact]
    public void Delete_Get_InvalidId_ReturnsNotFound()
    {
        var result = _sut.Delete(9999);

        Assert.IsType<NotFoundResult>(result);
    }

    // --- DeleteConfirmed ---

    [Fact]
    public void DeleteConfirmed_RemovesDepartmentAndRedirects()
    {
        var countBefore = _context.Departments.Count();

        var result = _sut.DeleteConfirmed(1);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
        Assert.Equal(countBefore - 1, _context.Departments.Count());
        Assert.Null(_context.Departments.Find(1));
    }
}

