using System;
using System.Collections.Generic;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests;

public class InstructorsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly InstructorsController _sut;

    public InstructorsControllerTests()
    {
        _context = TestHelpers.CreateSeededContext();
        // Add CourseAssignment and OfficeAssignment data for instructor tests
        SeedInstructorRelatedData(_context);
        _sut = new InstructorsController(_context);
    }

    private static void SeedInstructorRelatedData(SchoolContext context)
    {
        // Add an office assignment for instructor 1
        if (!context.OfficeAssignments.Any())
        {
            context.OfficeAssignments.Add(new OfficeAssignment
            {
                InstructorID = 1,
                Location = "Smith 17"
            });
            context.SaveChanges();
        }

        // Add course assignments
        if (!context.CourseAssignments.Any())
        {
            context.CourseAssignments.Add(new CourseAssignment
            {
                InstructorID = 1,
                CourseID = 1050
            });
            context.CourseAssignments.Add(new CourseAssignment
            {
                InstructorID = 2,
                CourseID = 4022
            });
            context.SaveChanges();
        }
    }

    public void Dispose()
    {
        _sut.Dispose();
        _context.Dispose();
    }

    // --- Index ---

    [Fact]
    public void Index_NoSelection_ReturnsViewWithAllInstructors()
    {
        var result = _sut.Index(null, null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<InstructorIndexData>(result.Model);
        Assert.Equal(2, model.Instructors.Count());
    }

    [Fact]
    public void Index_WithInstructorId_PopulatesCoursesForSelectedInstructor()
    {
        var result = _sut.Index(1, null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<InstructorIndexData>(result.Model);
        Assert.NotNull(model.Courses);
        Assert.Contains(model.Courses, c => c.CourseID == 1050);
    }

    [Fact]
    public void Index_WithCourseId_PopulatesEnrollmentsForSelectedCourse()
    {
        var result = _sut.Index(1, 1050) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<InstructorIndexData>(result.Model);
        Assert.NotNull(model.Enrollments);
    }

    [Fact]
    public void Index_InstructorsOrderedByLastName()
    {
        var result = _sut.Index(null, null) as ViewResult;

        var model = Assert.IsType<InstructorIndexData>(result!.Model);
        var instructors = model.Instructors.ToList();
        Assert.Equal("Abercrombie", instructors[0].LastName);
        Assert.Equal("Fakhouri", instructors[1].LastName);
    }

    // --- Details ---

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        var result = _sut.Details(null);

        Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, ((StatusCodeResult)result).StatusCode);
    }

    [Fact]
    public void Details_ValidId_ReturnsViewWithInstructor()
    {
        var result = _sut.Details(1) as ViewResult;

        Assert.NotNull(result);
        var instructor = Assert.IsType<Instructor>(result.Model);
        Assert.Equal("Abercrombie", instructor.LastName);
        Assert.Equal("Kim", instructor.FirstMidName);
    }

    [Fact]
    public void Details_InvalidId_ReturnsNotFound()
    {
        var result = _sut.Details(9999);

        Assert.IsType<NotFoundResult>(result);
    }

    // --- Create GET ---

    [Fact]
    public void Create_Get_ReturnsViewWithInstructorAndCourseData()
    {
        var result = _sut.Create() as ViewResult;

        Assert.NotNull(result);
        var instructor = Assert.IsType<Instructor>(result.Model);
        Assert.NotNull(instructor.CourseAssignments);
        Assert.NotNull(_sut.ViewBag.Courses);
    }

    // --- Create POST ---

    [Fact]
    public void Create_Post_ValidInstructor_RedirectsToIndex()
    {
        var instructor = new Instructor
        {
            FirstMidName = "New",
            LastName = "Instructor",
            HireDate = new DateTime(2020, 1, 1),
            CourseAssignments = new List<CourseAssignment>()
        };

        var result = _sut.Create(instructor, null!);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
    }

    [Fact]
    public void Create_Post_ValidInstructor_SavesDatabase()
    {
        var instructor = new Instructor
        {
            FirstMidName = "SavedFirst",
            LastName = "SavedLast",
            HireDate = new DateTime(2020, 1, 1),
            CourseAssignments = new List<CourseAssignment>()
        };

        _sut.Create(instructor, null!);

        var saved = _context.Instructors.FirstOrDefault(i => i.LastName == "SavedLast");
        Assert.NotNull(saved);
        Assert.Equal("SavedFirst", saved.FirstMidName);
    }

    [Fact]
    public void Create_Post_WithSelectedCourses_AddsCourseAssignments()
    {
        var instructor = new Instructor
        {
            FirstMidName = "Course",
            LastName = "Adder",
            HireDate = new DateTime(2020, 1, 1)
        };
        var selectedCourses = new[] { "1050", "4022" };

        _sut.Create(instructor, selectedCourses);

        var saved = _context.Instructors.Include(i => i.CourseAssignments)
            .FirstOrDefault(i => i.LastName == "Adder");
        Assert.NotNull(saved);
        Assert.Equal(2, saved.CourseAssignments.Count);
    }

    [Fact]
    public void Create_Post_InvalidModelState_ReturnsView()
    {
        _sut.ModelState.AddModelError("LastName", "Required");
        var instructor = new Instructor
        {
            FirstMidName = "Test",
            HireDate = new DateTime(2020, 1, 1),
            CourseAssignments = new List<CourseAssignment>()
        };

        var result = _sut.Create(instructor, null!) as ViewResult;

        Assert.NotNull(result);
    }

    // --- Edit GET ---

    [Fact]
    public void Edit_Get_NullId_ReturnsBadRequest()
    {
        var result = _sut.Edit((int?)null);

        Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, ((StatusCodeResult)result).StatusCode);
    }

    [Fact]
    public void Edit_Get_ValidId_ReturnsViewWithInstructor()
    {
        var result = _sut.Edit((int?)1) as ViewResult;

        Assert.NotNull(result);
        var instructor = Assert.IsType<Instructor>(result.Model);
        Assert.Equal("Abercrombie", instructor.LastName);
    }

    // --- Delete GET ---

    [Fact]
    public void Delete_Get_NullId_ReturnsBadRequest()
    {
        var result = _sut.Delete(null);

        Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, ((StatusCodeResult)result).StatusCode);
    }

    [Fact]
    public void Delete_Get_ValidId_ReturnsViewWithInstructor()
    {
        var result = _sut.Delete(1) as ViewResult;

        Assert.NotNull(result);
        var instructor = Assert.IsType<Instructor>(result.Model);
        Assert.Equal("Abercrombie", instructor.LastName);
    }

    [Fact]
    public void Delete_Get_InvalidId_ReturnsNotFound()
    {
        var result = _sut.Delete(9999);

        Assert.IsType<NotFoundResult>(result);
    }

    // --- DeleteConfirmed ---

    [Fact]
    public void DeleteConfirmed_RemovesInstructorAndRedirects()
    {
        // Use instructor 2 since instructor 1 has office assignment
        var countBefore = _context.Instructors.Count();

        var result = _sut.DeleteConfirmed(2);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
        Assert.Equal(countBefore - 1, _context.Instructors.Count());
    }

    [Fact]
    public void DeleteConfirmed_InstructorIsAdministrator_NullifiesDepartmentAdministrator()
    {
        // Instructor 1 is administrator of Department 1
        var dept = _context.Departments.Find(1);
        Assert.Equal(1, dept!.InstructorID);

        _sut.DeleteConfirmed(1);

        // Reload from DB
        var updatedDept = _context.Departments.Find(1);
        Assert.Null(updatedDept!.InstructorID);
    }
}

