using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;
using System;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests;

public class SchoolContextTests
{
    [Fact]
    public void SchoolContext_CanAddAndRetrieveStudent()
    {
        using var context = TestHelpers.CreateInMemoryContext();
        var student = new Student
        {
            FirstMidName = "Test",
            LastName = "Student",
            EnrollmentDate = new DateTime(2020, 1, 1)
        };

        context.Students.Add(student);
        context.SaveChanges();

        var retrieved = context.Students.First();
        Assert.Equal("Test", retrieved.FirstMidName);
        Assert.Equal("Student", retrieved.LastName);
        Assert.Equal(new DateTime(2020, 1, 1), retrieved.EnrollmentDate);
    }

    [Fact]
    public void SchoolContext_CanAddAndRetrieveCourse()
    {
        using var context = TestHelpers.CreateInMemoryContext();
        var dept = new Department
        {
            DepartmentID = 1,
            Name = "TestDept",
            Budget = 100000,
            StartDate = new DateTime(2020, 1, 1)
        };
        context.Departments.Add(dept);
        context.SaveChanges();

        var course = new Course
        {
            CourseID = 101,
            Title = "Test Course",
            Credits = 3,
            DepartmentID = 1
        };
        context.Courses.Add(course);
        context.SaveChanges();

        var retrieved = context.Courses.Find(101);
        Assert.NotNull(retrieved);
        Assert.Equal("Test Course", retrieved.Title);
        Assert.Equal(3, retrieved.Credits);
        Assert.Equal(1, retrieved.DepartmentID);
    }

    [Fact]
    public void SchoolContext_CourseAssignment_HasCompositeKey()
    {
        using var context = TestHelpers.CreateInMemoryContext();

        var instructor = new Instructor
        {
            ID = 1,
            FirstMidName = "Test",
            LastName = "Instructor",
            HireDate = new DateTime(2020, 1, 1)
        };
        context.Instructors.Add(instructor);

        var dept = new Department
        {
            DepartmentID = 1,
            Name = "TestDept",
            Budget = 100000,
            StartDate = new DateTime(2020, 1, 1)
        };
        context.Departments.Add(dept);

        var course = new Course
        {
            CourseID = 101,
            Title = "Test",
            Credits = 3,
            DepartmentID = 1
        };
        context.Courses.Add(course);
        context.SaveChanges();

        var assignment = new CourseAssignment
        {
            InstructorID = 1,
            CourseID = 101
        };
        context.CourseAssignments.Add(assignment);
        context.SaveChanges();

        var retrieved = context.CourseAssignments
            .FirstOrDefault(ca => ca.CourseID == 101 && ca.InstructorID == 1);
        Assert.NotNull(retrieved);
    }

    [Fact]
    public void SchoolContext_OfficeAssignment_LinkedToInstructor()
    {
        using var context = TestHelpers.CreateInMemoryContext();

        var instructor = new Instructor
        {
            ID = 1,
            FirstMidName = "Test",
            LastName = "Instructor",
            HireDate = new DateTime(2020, 1, 1)
        };
        context.Instructors.Add(instructor);
        context.SaveChanges();

        var office = new OfficeAssignment
        {
            InstructorID = 1,
            Location = "Room 101"
        };
        context.OfficeAssignments.Add(office);
        context.SaveChanges();

        var retrieved = context.OfficeAssignments.Find(1);
        Assert.NotNull(retrieved);
        Assert.Equal("Room 101", retrieved.Location);
        Assert.Equal(1, retrieved.InstructorID);
    }

    [Fact]
    public void SchoolContext_Enrollment_LinksStudentAndCourse()
    {
        using var context = TestHelpers.CreateInMemoryContext();

        var student = new Student
        {
            ID = 1,
            FirstMidName = "Test",
            LastName = "Student",
            EnrollmentDate = new DateTime(2020, 1, 1)
        };
        context.Students.Add(student);

        var dept = new Department
        {
            DepartmentID = 1,
            Name = "TestDept",
            Budget = 100000,
            StartDate = new DateTime(2020, 1, 1)
        };
        context.Departments.Add(dept);

        var course = new Course
        {
            CourseID = 101,
            Title = "Test",
            Credits = 3,
            DepartmentID = 1
        };
        context.Courses.Add(course);
        context.SaveChanges();

        var enrollment = new Enrollment
        {
            StudentID = 1,
            CourseID = 101,
            Grade = Grade.B
        };
        context.Enrollments.Add(enrollment);
        context.SaveChanges();

        var retrieved = context.Enrollments.First();
        Assert.Equal(1, retrieved.StudentID);
        Assert.Equal(101, retrieved.CourseID);
        Assert.Equal(Grade.B, retrieved.Grade);
    }

    [Fact]
    public void SchoolContext_Enrollment_GradeCanBeNull()
    {
        using var context = TestHelpers.CreateInMemoryContext();

        var student = new Student
        {
            ID = 1,
            FirstMidName = "Test",
            LastName = "Student",
            EnrollmentDate = new DateTime(2020, 1, 1)
        };
        context.Students.Add(student);

        var dept = new Department
        {
            DepartmentID = 1,
            Name = "TestDept",
            Budget = 100000,
            StartDate = new DateTime(2020, 1, 1)
        };
        context.Departments.Add(dept);

        var course = new Course
        {
            CourseID = 101,
            Title = "Test",
            Credits = 3,
            DepartmentID = 1
        };
        context.Courses.Add(course);
        context.SaveChanges();

        var enrollment = new Enrollment
        {
            StudentID = 1,
            CourseID = 101,
            Grade = null
        };
        context.Enrollments.Add(enrollment);
        context.SaveChanges();

        var retrieved = context.Enrollments.First();
        Assert.Null(retrieved.Grade);
    }

    [Fact]
    public void SchoolContext_Department_CanHaveNullInstructorID()
    {
        using var context = TestHelpers.CreateInMemoryContext();

        var dept = new Department
        {
            DepartmentID = 1,
            Name = "NoAdmin",
            Budget = 50000,
            StartDate = new DateTime(2020, 1, 1),
            InstructorID = null
        };
        context.Departments.Add(dept);
        context.SaveChanges();

        var retrieved = context.Departments.Find(1);
        Assert.NotNull(retrieved);
        Assert.Null(retrieved.InstructorID);
    }

    [Fact]
    public void SchoolContext_Notification_CanAddAndRetrieve()
    {
        using var context = TestHelpers.CreateInMemoryContext();

        var notification = new Notification
        {
            EntityType = "Student",
            EntityId = "42",
            Operation = "CREATE",
            Message = "New Student created",
            CreatedAt = new DateTime(2024, 1, 15),
            CreatedBy = "admin",
            IsRead = false
        };
        context.Notifications.Add(notification);
        context.SaveChanges();

        var retrieved = context.Notifications.First();
        Assert.Equal("Student", retrieved.EntityType);
        Assert.Equal("42", retrieved.EntityId);
        Assert.Equal("CREATE", retrieved.Operation);
        Assert.Equal("New Student created", retrieved.Message);
        Assert.Equal("admin", retrieved.CreatedBy);
        Assert.False(retrieved.IsRead);
    }
}

