[Fact]
public void Edit_Post_ValidStudent_RedirectsToIndex()
{
    // Detach tracked entity to avoid tracking conflict
    var tracked = _context.Students.Find(10);
    _context.Entry(tracked!).State = EntityState.Detached;

    var student = new Student
    {
        ID = 10,
        FirstMidName = "Carson",
        LastName = "Updated",
        EnrollmentDate = new DateTime(2010, 9, 1)
    };

    var result = _sut.Edit(student: student);

    var redirect = Assert.IsType<RedirectToActionResult>(result);
    Assert.Equal("Index", redirect.ActionName);
}

[Fact]
public void Edit_Post_ValidStudent_UpdatesDatabase()
{
    // Detach tracked entity to avoid tracking conflict
    var tracked = _context.Students.Find(10);
    _context.Entry(tracked!).State = EntityState.Detached;

    var student = new Student
    {
        ID = 10,
        FirstMidName = "ModifiedName",
        LastName = "Alexander",
        EnrollmentDate = new DateTime(2010, 9, 1)
    };

    _sut.Edit(student: student);

    // Re-read from a fresh query to avoid caching
    var updated = _context.Students.AsNoTracking().First(s => s.ID == 10);
    Assert.Equal("ModifiedName", updated.FirstMidName);
}

