    // --- DeleteConfirmed ---

    [Fact]
    public void DeleteConfirmed_ValidId_RemovesStudentAndRedirects()
    {
        var countBefore = _context.Students.Count();

        var result = _sut.DeleteConfirmed(10);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
        Assert.Equal(countBefore - 1, _context.Students.Count());
        Assert.Null(_context.Students.Find(10));
    }

    // --- Boundary date tests (mutation gap) ---

    [Fact]
    public void Create_Post_ExactSqlMinDate_IsAccepted()
    {
        // The exact boundary of 1753-01-01 should be valid
        var student = new Student
        {
            FirstMidName = "Boundary",
            LastName = "Test",
            EnrollmentDate = new DateTime(1753, 1, 1)
        };

        var result = _sut.Create(student);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
    }

    [Fact]
    public void Create_Post_OneDayBeforeSqlMin_IsRejected()
    {
        var student = new Student
        {
            FirstMidName = "TooEarly",
            LastName = "Student",
            EnrollmentDate = new DateTime(1752, 12, 31)
        };

        var result = _sut.Create(student) as ViewResult;

        Assert.NotNull(result);
        Assert.True(_sut.ModelState.ContainsKey("EnrollmentDate"));
    }

    // --- Page size test (mutation gap) ---

    [Fact]
    public void Index_PaginatesTo10ItemsPerPage()
    {
        // Add more students to exceed page size
        for (int i = 0; i < 15; i++)
        {
            _context.Students.Add(new Student
            {
                FirstMidName = $"Student{i}",
                LastName = $"ZZLast{i:D2}",
                EnrollmentDate = new DateTime(2020, 1, 1)
            });
        }
        _context.SaveChanges();

        // 3 seeded + 15 added = 18 students, page size 10 → first page has 10
        var result = _sut.Index(null, null, null, 1) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Equal(10, model.Count);
        Assert.True(model.HasNextPage);
        Assert.Equal(2, model.TotalPages);
    }
}

